def forward(self, x: torch.Tensor) -> torch.Tensor:
    """Pad on the left and convolve.

    Args:
        x: Input of shape ``(B, C, T)``.

    Returns:
        Output of shape ``(B, C, T)``.
    """
    if self.left_padding > 0:
        x = F.pad(x, (self.left_padding, 0))
    return self.conv(x)
